/// A completed solve: the plain result fields plus ownership of the
/// full Rust result behind them. report()/pretty_report() render the
/// Rust-side text (status, cost, the timing breakdown and the
/// backend's plan when gathered); plan() returns the sparse backend's
/// SchurPlan as data, gpu() what the solve did on its GPU, steps() the
/// per-attempt timeline, threads() what the threads did, covariance()
/// the covariance the config asked for.
/// Copies share ownership of the Rust result.
class LmResult : public LmResultT<float> {
public:
    LmResult() : LmResultT<float>() {}
    explicit LmResult(const LmResultT<float>& raw) : LmResultT<float>(raw) {
        if (detail)
            guard_ = std::shared_ptr<void>(detail, ffi::decay_result_free);
    }
    /// Text report; the pointer is valid until the next report call
    /// on this result or the destruction of its last copy.
    const char* report() const {
        return detail ? ffi::decay_result_report(detail, false) : "";
    }
    /// report() with colour and box-drawing glyphs.
    const char* pretty_report() const {
        return detail ? ffi::decay_result_report(detail, true) : "";
    }
    /// The sparse backend's plan; empty for dense and band solves.
    option<SchurPlan> plan() const {
        SchurPlan p;
        if (detail && ffi::decay_result_plan(detail, &p))
            return p;
        return {};
    }
    /// What the solve did on the GPU it was given (SparseOptions::gpu);
    /// empty for a solve without one. Its strings are valid until the
    /// destruction of this result's last copy.
    option<GpuReport> gpu() const {
        GpuReport g;
        if (detail && ffi::decay_result_gpu(detail, &g))
            return g;
        return {};
    }
    /// The per-attempt timeline (Rust's LmTiming::steps); empty
    /// unless the solve ran with gather_timing.
    std::vector<LmStep> steps() const {
        std::vector<LmStep> out;
        if (!detail)
            return out;
        out.resize(ffi::decay_result_steps(detail, nullptr, 0));
        if (!out.empty())
            ffi::decay_result_steps(detail, out.data(), out.size());
        return out;
    }
    /// What the solve's threads did (Rust's ThreadReport).
    ThreadReport threads() const {
        ThreadReport t{};
        if (detail)
            ffi::decay_result_threads(detail, &t);
        return t;
    }
    /// What each split store held (Rust's SweepReport::held); empty
    /// without a threaded sweep.
    std::vector<StoreFootprint> threads_held() const {
        std::vector<StoreFootprint> out;
        if (!detail)
            return out;
        out.resize(ffi::decay_result_threads_held(detail, nullptr, 0));
        if (!out.empty())
            ffi::decay_result_threads_held(detail, out.data(), out.size());
        return out;
    }
    /// The covariance the config asked for (LmConfig::covariance),
    /// assembled at the solution, moved out of the result into the
    /// view; the error names why there is none (the config did not
    /// ask, an earlier call took it, or the assembly failed).
    result<Covariance, CovError> covariance() const;

private:
    std::shared_ptr<void> guard_;
};

/// The Err side of a solve (Rust's SolveFailure): SolverFailed, the
